<?php $section = 'orders'; require __DIR__ . '/../../partials/admin-nav.php'; ?>
<div class="page-heading"><div><span class="section-overline">QUẢN LÝ ĐƠN HÀNG</span><h1>Đơn hàng<span class="accent-period">.</span></h1><p><?= count($orders) ?> đơn hàng đã ghi nhận.</p></div><a href="<?= h(url('/admin/orders/create')) ?>" class="btn btn-primary">+ Tạo đơn hàng</a></div>
<div class="panel table-scroll"><table><thead><tr><th>Mã đơn</th><th>Khách hàng</th><th>Ngày đặt</th><th>Giá trị</th><th>Trạng thái</th><th>Thanh toán</th><th>Thao tác</th></tr></thead><tbody><?php foreach ($orders as $order): ?><tr><td><strong>#<?= (int) $order['id'] ?></strong></td><td><strong><?= h($order['customer_name']) ?></strong><div class="muted-text"><?= h($order['user_email'] ?? 'Tài khoản đã xóa') ?></div></td><td><?= h(date('d/m/Y', strtotime($order['created_at']))) ?></td><td class="price-cell"><?= money($order['total']) ?></td><td><span class="status status-<?= h($order['status']) ?>"><?= h(orderStatus($order['status'])) ?></span></td><td><?= h(paymentStatus($order['payment_status'])) ?></td><td><div class="action-group"><a class="btn btn-outline btn-sm" href="<?= h(url('/admin/orders/' . (int) $order['id'])) ?>">Sửa</a><form method="post" action="<?= h(url('/admin/orders/' . (int) $order['id'] . '/delete')) ?>" onsubmit="return confirm('Xóa đơn hàng này? Tồn kho sẽ được xử lý lại.')"><input type="hidden" name="_csrf" value="<?= h(\App\Core\Csrf::token()) ?>"><button type="submit" class="btn btn-danger btn-sm">Xóa</button></form></div></td></tr><?php endforeach; ?><?php if (!$orders): ?><tr><td colspan="7" class="no-data">Chưa có đơn hàng.</td></tr><?php endif; ?></tbody></table></div>
